     "ex": "import csv, logging, time\nfrom datetime import date\n\nlog = logging.getLogger(\"scraper\")\n\ndef enrich(books, delay=1.0):\n    failed = []\n    for b in books:\n        try:\n            html = cached_get(b[\"url\"], fetch=lambda u: SESSION.get(u, timeout=15).text)\n            b.update(parse_detail(html, b[\"url\"]))\n        except Exception:\n            log.exception(\"detail page failed: %s\", b[\"url\"])\n            failed.append(b[\"url\"])\n        time.sleep(delay)\n    return failed\n\ndef save_csv(rows, path):\n    with open(path, \"w\", newline=\"\", encoding=\"utf-8-sig\") as f:\n        w = csv.DictWriter(f, fieldnames=list(rows[0]) + [\"scraped_on\"])\n        w.writeheader()\n        w.writerows({**r, \"scraped_on\": date.today().isoformat()} for r in rows)"
